using System;using System.IO;using System.Linq;using System.Drawing;using System.Drawing.Imaging;using System.Reflection;using JouchoPet;
class MiSigilCheck {
 const string Folder="qa/v0747/";const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;static int count;
 static void Check(bool b,string label){if(!b)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
 static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,F).Invoke(o,args);}
 static object ConvertValue(object v,Type t){if(v==null||t.IsPrimitive||t==typeof(string))return v;var o=Activator.CreateInstance(t);foreach(var f in t.GetFields(F)){var a=v.GetType().GetField(f.Name,F);if(a!=null)f.SetValue(o,ConvertValue(a.GetValue(v),f.FieldType));}return o;}
 static Bitmap Scene(PetRenderer r,double age,bool effects,bool cross=false){var b=new Bitmap(960,540);using(var g=Graphics.FromImage(b)){g.Clear(Color.FromArgb(46,51,61));g.ScaleTransform(.5f,.5f);var pose=DailyMotion.At(DailyAction.Sigil,age);pose.SigilSeed=71;pose.CrossOnly=cross;var frame=r.Draw(new RenderFrame{MotionState="idle",Time=age,Daily=pose});int x=960-frame.Width/2,y=600-frame.Height/2;g.DrawImageUnscaled(frame,x,y);var face=r.SigilFace;face.Offset(x,y);if(effects)MiSigilArt.Draw(g,RigParts.Add(r.SigilAnchor,x,y),MiSigilArt.Span(new Size(1920,1080)),300,pose,face);}return b;}
 static Bitmap Effect(double age,int seed=71,RectangleF face=default(RectangleF),bool cross=false){var b=new Bitmap(600,600);using(var g=Graphics.FromImage(b)){var p=DailyMotion.At(DailyAction.Sigil,age);p.SigilSeed=seed;p.CrossOnly=cross;MiSigilArt.Draw(g,new PointF(300,300),400,300,p,face);}return b;}
 static void Geometry(){
  var old=Assembly.LoadFile(Path.GetFullPath(Folder+"baseline/IsekaijouchoPet.exe"));
  foreach(int size in new[]{220,300,400}){var c=PetRenderer.CanvasSize(size);using(var art=CharacterArt.Normalized("front",c.Width,c.Height,size))using(var rig=new GreetingArmRig(PoseMesh.Read(art),c.Width,c.Height,size)){
   object before=Activator.CreateInstance(old.GetType("JouchoPet.GreetingArmRig"),F,null,new object[]{PoseMesh.Read(art),c.Width,c.Height,(double)size},null);
   try{var rest=rig.SigilSample(0,0);var prev=rest;bool valid=true,stationary=true;for(int i=0;i<=200;i++){double q=i/200.0;var p=rig.SigilSample(q,0);double projected=RigParts.Length(p.Shoulder,p.Elbow);valid&=Math.Abs(Math.Sqrt(projected*projected+p.UpperDepth*p.UpperDepth)-RigParts.Length(rest.Shoulder,rest.Elbow))<.001&&Math.Abs(RigParts.Length(p.Elbow,p.Wrist)-RigParts.Length(rest.Elbow,rest.Wrist))<.001&&RigParts.Length(prev.Elbow,p.Elbow)<size*.02;
    stationary&=Math.Abs(p.UpperAngle)<.001&&RigParts.Length(prev.Wrist,p.Wrist)<size*.02;prev=p;
   }Check(valid,"physical bone lengths and elbow continuity / "+size);Check(stationary,"upper arm direction fixed with continuous forearm lift / "+size);
   var held=rig.SigilSample(1,0);var heldOld=Call(before,"SigilSample",1.0,0.0);Check(RigParts.Length(RigParts.Mix(held.Wrist,held.Tip,.65),RigParts.Mix((PointF)heldOld.GetType().GetField("Wrist",F).GetValue(heldOld),(PointF)heldOld.GetType().GetField("Tip",F).GetValue(heldOld),.65))<.001,"held fist and sigil origin preserved / "+size);
   }finally{((IDisposable)before).Dispose();}
  }}
  Check(Math.Abs(MiSigilArt.ArmWidth(300)-5.25)<.00001&&MiSigilArt.Span(new Size(1920,1080))==540,"current half-width and original screen span");
  var center=new PointF(-330,470);bool straight=true;for(int i=0;i<4;i++){var ends=MiSigilArt.Ends(center,540,i);straight&=RigParts.Length(RigParts.Mix(ends[0],ends[1],.5),center)<.001&&Math.Abs(RigParts.Length(ends[0],ends[1])-540)<.001;}Check(straight,"four straight axes at negative screen coordinates");
 }
 static void CrossVariant(){
  bool cardinals=true,diagonals=true,original=true;var old=Assembly.LoadFile(Path.GetFullPath(Folder+"baseline/IsekaijouchoPet.exe"));
  foreach(double t in new[]{.70,.85,1.20,1.36})using(var mi=Effect(t))using(var cross=Effect(t,71,default(RectangleF),true))using(var previous=new Bitmap(600,600))using(var g=Graphics.FromImage(previous)){
   var pose=DailyMotion.At(DailyAction.Sigil,t);pose.SigilSeed=71;old.GetType("JouchoPet.MiSigilArt").GetMethod("Draw",F).Invoke(null,new object[]{g,new PointF(300,300),400.0,300.0,ConvertValue(pose,old.GetType("JouchoPet.DailyPose")),default(RectangleF)});original&=PoseMesh.Read(mi).SequenceEqual(PoseMesh.Read(previous));
   for(int x=355;x<500;x++)for(int y=285;y<=315;y++)cardinals&=mi.GetPixel(x,y)==cross.GetPixel(x,y);
   for(int x=380;x<420;x++)for(int y=380;y<420;y++)diagonals&=cross.GetPixel(x,y).A==0;
  }
  Check(original,"Mi effect unchanged after brief synchronized flash");Check(cardinals,"Cross retains identical horizontal rays, arcs and breakup");Check(diagonals,"Cross removes diagonal bodies, arcs and shards");
  var p=DailyMotion.At(DailyAction.Sigil,.85);p.CrossOnly=true;Check(p.Scale(.5).CrossOnly,"variant retained through pose scaling");
 }
 static void Effects(){
  using(var a=Effect(.85))using(var b=Effect(.94))using(var repeat=Effect(.85))using(var other=Effect(.85,72)){
   Check(!PoseMesh.Read(a).SequenceEqual(PoseMesh.Read(b)),"arcs change during stable hold");Check(PoseMesh.Read(a).SequenceEqual(PoseMesh.Read(repeat)),"same time and request render deterministically");Check(!PoseMesh.Read(a).SequenceEqual(PoseMesh.Read(other)),"different requests have different arc patterns");
  }
  using(var a=new Bitmap(600,100))using(var b=new Bitmap(600,100))using(var ga=Graphics.FromImage(a))using(var gb=Graphics.FromImage(b)){
   ga.TranslateTransform(10,50);gb.TranslateTransform(10,50);var draw=typeof(MiSigilArt).GetMethod("DrawRay",F);draw.Invoke(null,new object[]{ga,200f,5.25f,.85,0,71,1.0});draw.Invoke(null,new object[]{gb,200f,5.25f,.94,0,71,1.0});
   Check(PoseMesh.Read(a).SequenceEqual(PoseMesh.Read(b)),"blade remains straight and stable while arcs vary");Check(a.GetPixel(80,50).R>85&&a.GetPixel(80,50).G<25&&a.GetPixel(80,54).R<10,"matte red fill and clear black border");Check(a.GetPixel(210,54).A==0,"blade tip has no rounded cap");
  }
  Check(MiSigilArt.Burst(.535)>.9&&MiSigilArt.Burst(.62)==0&&MiSigilArt.Burst(.9)==0,"one short center flash ends before hold");
  var opacities=Enumerable.Range(0,72).Select(k=>MiSigilArt.PieceOpacity(1.20,k/9,k%9,71)).ToArray();Check(opacities.Max()>.99&&opacities.Min()<.5,"local fracture preserves some pieces while others dissolve");Check(Enumerable.Range(0,72).All(k=>MiSigilArt.PieceOpacity(1.48,k/9,k%9,71)==0),"all blade fragments clear before return");
  using(var plain=Effect(.85))using(var masked=Effect(.85,71,new RectangleF(270,180,60,60)))Check(plain.GetPixel(300,210).A>0&&masked.GetPixel(300,210)==plain.GetPixel(300,210),"blades stay visible over former hair mask");
  using(var plain=Effect(.54))using(var masked=Effect(.54,71,new RectangleF(270,270,60,60)))Check(plain.GetPixel(300,300).R>masked.GetPixel(300,300).R,"only center flash is suppressed in face region");
  using(var b=Effect(1.60))Check(PoseMesh.Read(b).All(v=>v==0),"no effect residue during arm return");
 }
 static void Timeline(){
  Check(DailyMotion.Duration(DailyAction.Sigil)==2&&DailyMotion.At(DailyAction.Sigil,.35).Sigil==1,"raise and total duration unchanged");bool sync=true;for(int i=0;i<=100;i++){double t=.52+i*.16/100;var pose=DailyMotion.At(DailyAction.Sigil,t);sync&=Math.Abs(pose.Fist-pose.Glyph)<.000001;}Check(sync&&DailyMotion.At(DailyAction.Sigil,.51).Fist==0&&DailyMotion.At(DailyAction.Sigil,.68).Fist==1,"fist and glyph start and finish together");Check(DailyMotion.At(DailyAction.Sigil,.51).Glow==0&&MiSigilArt.Burst(.51)==0,"no flash before fist and sigil start");Check(DailyMotion.At(DailyAction.Sigil,.52).Glyph==0&&DailyMotion.At(DailyAction.Sigil,.68).Glyph==1,"eight directions expand in 0.16 seconds");
  foreach(int facing in new[]{-1,1}){var motion=new Motion();motion.FollowPush(0,0,facing,300);var d=new DailyMotion();d.Request(DailyAction.Sigil);d.Update(.016,false);Check(d.Pending&&!d.Active,"wait for front / "+facing);bool started=false;for(int i=0;i<480;i++){motion.Update(1.0/60,0,300);d.Update(1.0/60,motion.State=="idle"&&motion.Facing==0);if(d.Active){started=true;break;}}Check(started&&motion.Facing==0,"front-facing action starts / "+facing);d.Update(.8,true);d.Cancel();d.Update(.25,true);Check(!d.Busy&&d.Pose.Sigil==0,"cancel resets / "+facing);}
  var action=new DailyMotion();action.Request(DailyAction.Sigil);action.Update(.01,true);int seed=action.Pose.SigilSeed;action.Reset();action.Request(DailyAction.Sigil);action.Update(.01,true);Check(seed!=action.Pose.SigilSeed,"new invocation selects new effect seed");
 }
 static void Regression(){var old=Assembly.LoadFile(Path.GetFullPath(Folder+"baseline/IsekaijouchoPet.exe"));var type=old.GetType("JouchoPet.PetRenderer");object before=Activator.CreateInstance(type,true);using(var now=new PetRenderer()){now.Resize(300);Call(before,"Resize",300);try{foreach(var frame in new[]{new RenderFrame{MotionState="idle"},new RenderFrame{RestAmount=1},new RenderFrame{Daily=DailyMotion.At(DailyAction.Wink,.6)},new RenderFrame{Daily=DailyMotion.At(DailyAction.Hair,1.1)},new RenderFrame{Daily=DailyMotion.At(DailyAction.Thinking,.8)},new RenderFrame{Greeting=1,WaveBlend=1,ClosedEyes=1},new RenderFrame{MotionState="walk",Facing=-1,Speed=-198,RunBlend=1,Gait=.7},new RenderFrame{MotionState="walk",Facing=1,Speed=198,RunBlend=1,Gait=.7},new RenderFrame{Archery=true,BowPose=ArcheryMotion.At(2,1)}}){Check(PoseMesh.Read((Bitmap)Call(before,"Draw",ConvertValue(frame,old.GetType("JouchoPet.RenderFrame")))).SequenceEqual(PoseMesh.Read(now.Draw(frame))),"existing frame unchanged / "+frame.MotionState+" / "+frame.Facing);}
 foreach(int dir in new[]{-1,1}){var sw=SwordMotion.At(.6,dir);Check(PoseMesh.Read((Bitmap)Call(before,"DrawSword",ConvertValue(sw,old.GetType("JouchoPet.SwordPose")),true)).SequenceEqual(PoseMesh.Read(now.DrawSword(sw,true))),"sword unchanged / "+dir);var cast=CastingMotion.At(1.9,dir,25);Check(PoseMesh.Read((Bitmap)Call(before,"DrawCast",ConvertValue(cast,old.GetType("JouchoPet.CastPose")),true)).SequenceEqual(PoseMesh.Read(now.DrawCast(cast,true))),"cast unchanged / "+dir);}
 }finally{((IDisposable)before).Dispose();}}}
 static void Preview(){using(var r=new PetRenderer()){r.Resize(300);double[] times={0,.20,.35,.43,.54,.58,.62,.68,.85,.94,1.08,1.20,1.32,1.44,1.56,1.85};foreach(double t in times)using(var b=Scene(r,t,true))b.Save(Folder+"sigil-"+t.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+".png");using(var b=Scene(r,.68,false))b.Save(Folder+"body-only.png");
 using(var atlas=new Bitmap(960*6,540*9))using(var g=Graphics.FromImage(atlas)){for(int i=0;i<=48;i++)using(var b=Scene(r,i/24.0,true))g.DrawImageUnscaled(b,i%6*960,i/6*540);atlas.Save(Folder+"sigil-atlas.png");}
 using(var atlas=new Bitmap(960*6,540*9))using(var g=Graphics.FromImage(atlas)){for(int i=0;i<=48;i++)using(var b=Scene(r,i/24.0,true,true))g.DrawImageUnscaled(b,i%6*960,i/6*540);atlas.Save(Folder+"cross-atlas.png");}
 foreach(double t in new[]{.58,.85,1.20,1.36})using(var b=Scene(r,t,true,true))b.Save(Folder+"cross-"+t.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+".png");
 foreach(bool fracture in new[]{false,true})using(var atlas=new Bitmap(960*4,540*5))using(var g=Graphics.FromImage(atlas)){for(int i=0;i<20;i++)using(var b=Scene(r,fracture?1.05+i*.5/19:.52+i*.16/19,true))g.DrawImageUnscaled(b,i%4*960,i/4*540);atlas.Save(Folder+(fracture?"fracture-atlas.png":"expansion-atlas.png"));}
 using(var poses=new Bitmap(348*6,373))using(var g=Graphics.FromImage(poses)){g.Clear(Color.FromArgb(46,51,61));int i=0;foreach(double t in new[]{0,.35,.52,.60,.68,1.85}){g.DrawImageUnscaled(r.Draw(new RenderFrame{MotionState="idle",Time=t,Daily=DailyMotion.At(DailyAction.Sigil,t)}),i*348,25);g.DrawString(t.ToString("F2")+" s",SystemFonts.DefaultFont,Brushes.White,i*348+5,3);i++;}poses.Save(Folder+"fist-poses.png");}
 }
 using(var detail=new Bitmap(1200,1200))using(var g=Graphics.FromImage(detail)){g.Clear(Color.FromArgb(46,51,61));int i=0;foreach(double t in new[]{.58,.85,1.20,1.36})using(var b=Effect(t)){g.DrawImageUnscaled(b,i%2*600,i/2*600);g.DrawString(t.ToString("F2")+" s",SystemFonts.DefaultFont,Brushes.White,i%2*600+10,i/2*600+10);i++;}detail.Save(Folder+"sigil-detail.png");}
 using(var all=new Bitmap(1100,550))using(var g=Graphics.FromImage(all)){g.Clear(Color.FromArgb(46,51,61));int i=0;foreach(int size in new[]{220,300,400})using(var r=new PetRenderer()){r.Resize(size);var pose=DailyMotion.At(DailyAction.Sigil,.85);pose.SigilSeed=71;var body=r.Draw(new RenderFrame{MotionState="idle",Time=.85,Daily=pose});int x=i*360+180-body.Width/2,y=520-body.Height;g.DrawImageUnscaled(body,x,y);var face=r.SigilFace;face.Offset(x,y);MiSigilArt.Draw(g,RigParts.Add(r.SigilAnchor,x,y),280,size,pose,face);g.DrawString(size+" px",SystemFonts.DefaultFont,Brushes.White,i*360+10,10);i++;}all.Save(Folder+"sizes.png");}
 }
 [STAThread]static void Main(){try{Directory.CreateDirectory(Folder);AnimationParameters.UseFixedValues();Geometry();Effects();Timeline();CrossVariant();Regression();Preview();Console.WriteLine("All "+count+" checks passed. Offline rendering only; no live window opened.");}catch(Exception e){Console.WriteLine(e);Environment.ExitCode=1;}}
